        require(address(this).balance >= v);
        require(v <= type(uint256).max);
        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        require(beforeBal + v >= beforeBal);
        bool reverted;
        c.Deposit{value: v}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
