pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 v) internal {
        v = bound(v, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= v);
        vm.assume(v <= type(uint256).max);
        uint256 beforeBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        vm.assume(beforeBal + v >= beforeBal);
        bool reverted;
        try c.Deposit{value: v}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBal;
        try c.balances(address(this)) returns (uint256 __r) { afterBal = __r; } catch { return; }
        assertTrue(reverted || (afterBal == beforeBal + v && afterBal >= v));
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
